// Repro, bucket A: data bits must leave LSB first.
`timescale 1ns / 1ps
module tb_repro_data_order;
    localparam integer CPB = 4;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    integer i, k, guard;
    reg [8*64-1:0] nonce;
    reg [7:0] bytes [0:4];
    reg [7:0] d;

    task advance(input integer n);
        begin
            repeat (n) @(posedge clk);
            #1;
        end
    endtask

    task send_start(input [7:0] v);
        begin
            @(negedge clk);
            data  = v;
            start = 1'b1;
            @(posedge clk);
            #1;
            start = 1'b0;
        end
    endtask

    task wait_idle;
        begin
            guard = 0;
            while (busy && guard < 200) begin
                advance(1);
                guard = guard + 1;
            end
            advance(3);
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        bytes[0] = 8'h01; bytes[1] = 8'h80; bytes[2] = 8'hD2;
        bytes[3] = 8'h0F; bytes[4] = 8'h96;
        advance(4);
        @(negedge clk) rst = 1'b0;
        advance(3);
        for (i = 0; i < 5; i = i + 1) begin
            d = bytes[i];
            send_start(d);       // 1 ns after the capture edge E0
            advance(2);          // middle of the start bit
            for (k = 0; k < 8; k = k + 1) begin
                advance(CPB);    // middle of data slot k
                if (tx === d[k]) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $display("CHECK data_bit_order FAIL byte=%h slot=%0d expected=%b got=%b", d, k, d[k], tx);
                end
            end
            wait_idle;
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===

