// Repro, bucket C: a frame (start + 8 data + parity + stop) lasts 11 bit periods.
`timescale 1ns / 1ps
module tb_repro_frame_period;
    localparam integer CPB = 4;
    localparam integer FRAME_CYCLES = 11 * CPB;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    integer i, cnt;
    reg [8*64-1:0] nonce;
    reg [7:0] bytes [0:2];

    task advance(input integer n);
        begin
            repeat (n) @(posedge clk);
            #1;
        end
    endtask

    task send_start(input [7:0] v);
        begin
            @(negedge clk);
            data  = v;
            start = 1'b1;
            @(posedge clk);
            #1;
            start = 1'b0;
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        bytes[0] = 8'h55; bytes[1] = 8'h00; bytes[2] = 8'hFF;
        advance(4);
        @(negedge clk) rst = 1'b0;
        advance(3);
        for (i = 0; i < 3; i = i + 1) begin
            send_start(bytes[i]);   // 1 ns after the capture edge E0
            cnt = 0;
            while (busy && cnt < 200) begin
                cnt = cnt + 1;
                advance(1);
            end
            if (cnt == FRAME_CYCLES) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK frame_period FAIL frame=%0d expected=%0d got=%0d busy cycles", i, FRAME_CYCLES, cnt);
            end
            if (tx === 1'b1) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK idle_line_high FAIL frame=%0d got=%b", i, tx);
            end
            advance(3);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
